import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';
const root = resolve(process.argv[2]);
const packageRoot = join(root, 'node_modules/@modainteract/moda-interact-shared');
const pkg = JSON.parse(await readFile(join(packageRoot, 'package.json'), 'utf8'));
const entry = pkg.exports['./commerce'].import;
const shared = await import(pathToFileURL(join(packageRoot, entry)).href);
const requireFromShared = createRequire(join(packageRoot, 'package.json'));
const resolvedZodPath = requireFromShared.resolve('zod/package.json');
const resolvedZod = JSON.parse(await readFile(resolvedZodPath, 'utf8'));
const results = [];
for (const descriptor of shared.commerceDiscountBuiltInDescriptors) {
  const payload = shared.commerceBuiltInToolContractPayload(descriptor);
  const observed = createHash('sha256').update(payload).digest('hex');
  await writeFile(join(root, `${descriptor.name}.payload.json`), payload + '\n');
  results.push({name:descriptor.name, definitionVersion:descriptor.definitionVersion, recorded:descriptor.contractHash, observed, matches:observed === descriptor.contractHash, trusted:shared.isTrustedCommerceBuiltInDescriptor(descriptor), payloadBytes:Buffer.byteLength(payload)});
}
const report={node:process.version,sharedVersion:pkg.version,sharedDeclaredZod:pkg.dependencies.zod,resolvedZod:resolvedZod.version,resolvedZodPath,results};
await writeFile(join(root,'result.json'),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(report,null,2));
process.exitCode=results.every(r=>r.matches)?0:1;
